value":{"name":"shell","arguments":{"command":"python3 << 'EOF'\n# For 1970 data - parse the table to find regular weekly/annual and tax anticipation bills\n\n# From the 1970 data:\n# Regular weekly and annual maturing (Jan 1970 through Dec 1970):\nregular_1970 = [1501, 13510, 13516, 16525, 6308, 6512, 7721, 1701, 1505, 1003, 1001, 1002]\n# Tax anticipation bills:\ntax_1970 = [1752, 3014, 4508]\n\n# From the 1975 data:\n# Regular weekly and annual maturing (Feb 1975 through Jan 1976):\nregular_1975 = [20916, 20031, 20328, 14812, 13517, 14819, 1803, 1803, 2003, 2002, 2001, 2001]\n# Tax anticipation bills:\ntax_1975 = [2251, 1256]\n\n# Calculate totals\ntotal_regular_1970 = sum(regular_1970)\ntotal_tax_1970 = sum(tax_1970)\n\ntotal_regular_1975 = sum(regular_1975)\ntotal_tax_1975 = sum(tax_1975)\n\nprint(\"1970 Data:\")\nprint(f\"Regular weekly and annual maturing total: {total_regular_1970}\")\nprint(f\"Tax anticipation total: {total_tax_1970}\")\n\nprint(\"\\n1975 Data:\")\nprint(f\"Regular weekly and annual maturing total: {total_regular_1975}\")\nprint(f\"Tax anticipation total: {total_tax_1975}\")\n\n# Absolute changes\nabs_change_regular = abs(total_regular_1975 - total_regular_1970)\nabs_change_tax = abs(total_tax_1975 - total_tax_1970)\n\nprint(f\"\\nAbsolute change regular weekly/annual: {abs_change_regular}\")\nprint(f\"Absolute change tax anticipation: {abs_change_tax}\")\n\n# Euclidean norm\nimport math\neuclidean_norm = math.sqrt(abs_change_regular**2 + abs_change_tax**2)\nprint(f\"\\nEuclidean norm: {euclidean_norm}\")\nprint(f\"Rounded to nearest hundredth: {round(euclidean_norm, 2)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
